let trigger = {};
try {
  const triggerItems = $('When Executed by Another Workflow').all();
  trigger = triggerItems.length ? triggerItems[0].json : {};
} catch (e) { trigger = {}; }
const asOfDate = trigger.asOfDate || new Date().toISOString().slice(0, 10);
return $input.all().map((item) => ({ json: { ...item.json, asOfDate } }));

const count = $input.first().json.row_count;
return [{ json: {
  workflow: '18-egx-range-forecast',
  finishedAt: new Date().toISOString(),
  rangeForecastRowCount: count,
} }];

parameters.query:
SELECT json_agg(t.* ORDER BY t.date ASC) AS candles
FROM (
  SELECT trading_date AS date, open, high, low, close, volume
  FROM daily_prices
  WHERE stock_id = $1 AND trading_date <= $2
) t;

