function isNumber(v) { return typeof v === 'number' && Number.isFinite(v); }
function round(v, d) { if (!isNumber(v)) return null; const f = Math.pow(10, d); return Math.round(v * f) / f; }
function atr14(candles) {
  const period = 14;
  const out = new Array(candles.length).fill(null);
  if (candles.length < period + 1) return out;
  const trueRanges = candles.map((c, i) => {
    if (i === 0) return c.high - c.low;
    const prevClose = candles[i - 1].close;
    return Math.max(c.high - c.low, Math.abs(c.high - prevClose), Math.abs(c.low - prevClose));
  });
  let avgTr = trueRanges.slice(1, period + 1).reduce((a, b) => a + b, 0) / period;
  out[period] = avgTr;
  for (let i = period + 1; i < candles.length; i++) {
    avgTr = (avgTr * (period - 1) + trueRanges[i]) / period;
    out[i] = avgTr;
  }
  return out;
}

const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  let original;
  try { original = $('Attach As-Of Date').itemMatching(i).json; } catch (e) { continue; }
  const stockId = original.id;

  const row = items[i].json;
  const rawCandles = row.candles || [];
  if (!Array.isArray(rawCandles) || rawCandles.length < 16) continue;

  const candles = [...rawCandles].sort((a, b) => new Date(a.date) - new Date(b.date));
  const atrSeries = atr14(candles);

  // One forecast row per bar with a valid ATR (full history, idempotent
  // backfill on every run). accuracyPct at bar k is the expanding-window
  // containment rate over bars 14..k-1 ONLY -- data available as of that
  // date, nothing from the future. The final bar's row is numerically
  // identical to what the previous single-row version of this node emitted.
  const rows = [];
  let contained = 0;
  let total = 0;
  for (let k = 14; k < candles.length; k++) {
    if (!isNumber(atrSeries[k])) continue;
    rows.push({
      tradingDate: candles[k].date,
      close: candles[k].close,
      nextHighEstimate: round(candles[k].close + atrSeries[k], 6),
      nextLowEstimate: round(candles[k].close - atrSeries[k], 6),
      accuracyPct: total > 0 ? round((contained / total) * 100, 2) : null,
      sampleSize: total,
    });
    // This bar's own outcome becomes known the NEXT session; fold it into
    // the running counters so it counts toward accuracy from bar k+1 on.
    if (k < candles.length - 1) {
      const predictedHigh = candles[k].close + atrSeries[k];
      const predictedLow = candles[k].close - atrSeries[k];
      total++;
      if (candles[k + 1].high <= predictedHigh && candles[k + 1].low >= predictedLow) contained++;
    }
  }
  if (!rows.length) continue;

  // ONE item per stock carrying the rows as a JSON string -- emitting one
  // item per bar (250k+ at US scale) would repeat the OOM pattern that
  // crashed workflows 04/05 before they were batched.
  out.push({ json: { stockId, rowsJson: JSON.stringify(rows) } });
}

return out;
